"""Program 14: Leap Year Checker
Checks if a year is a leap year."""
def is_leap_year(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0

def main():
    year = int(input("Enter a year: "))
